mapper.update:
UPDATE interview_session
SET
    current_interview_question_id = #{followUpQuestionId},
    version = version + 1
WHERE id = #{id}
    AND version = #{expectedVersion}
    AND status = 'IN_PROGRESS'
    AND current_interview_question_id = #{expectedCurrentQuestionId}

UPDATE interview_session
SET
    current_interview_question_id = #{nextMainQuestionId},
    completed_question_count = completed_question_count + 1,
    version = version + 1
WHERE id = #{id}
    AND version = #{expectedVersion}
    AND status = 'IN_PROGRESS'
    AND current_interview_question_id = #{expectedCurrentQuestionId}
    AND completed_question_count < planned_question_count

UPDATE interview_session
SET
    report_status = 'GENERATING',
    version = version + 1
WHERE id = #{id}
    AND version = #{expectedVersion}
    AND status = 'COMPLETED'
    AND report_status = #{expectedReportStatus}
    AND report_status IN ('NOT_STARTED', 'FAILED')
